using namespace cg3::cgal::internal;
using namespace cg3;

std::vector<std::vector<Point2d>> result;
result.reserve(points.size());

// Create Delaunay triangulation
DT dt;
dt.insert(points.begin(), points.end());

// Create Voronoi diagram
VD vd(dt);

// Map from Voronoi vertices to indices
std::map<Point_2, unsigned int> vertex_map;
std::vector<Point_2> vertices;

// Process each Voronoi face
for (VD::Face_iterator fit = vd.faces_begin(); fit != vd.faces_end(); ++fit) {
    if (fit->is_unbounded()) continue;

    std::vector<Point2d> cell_vertices;
    cell_vertices.reserve(3); // Voronoi cells are typically polygons with 3+ vertices

    // Get the infinite vertex of the face
    Vertex_handle vh = fit->outer_ccb()->vertex();
    Point_2 v = vh->point();
    cell_vertices.push_back(Point2d(v.x(), v.y()));

    // Get the finite vertices of the face
    for (Ccb_halfedge_circulator cit = fit->ccb(); cit != 0; ++cit) {
        if (cit->vertex()->is_finite()) {
            Point_2 p = cit->vertex()->point();
            cell_vertices.push_back(Point2d(p.x(), p.y()));
        }
    }

    // Ensure we have at least 3 vertices (for unbounded cells)
    if (cell_vertices.size() < 3) {
        // Find the two adjacent faces to get more vertices
        Halfedge_handle he = fit->halfedge();
        Face_handle f1 = he->next()->face();
        Face_handle f2 = he->prev()->face();

        if (f1 != vd.infinite_face() && f2 != vd.infinite_face()) {
            // Get vertices from adjacent faces
            for (Ccb_halfedge_circulator cit = f1->ccb(); cit != 0; ++cit) {
                if (cit->vertex()->is_finite()) {
                    Point_2 p = cit->vertex()->point();
                    cell_vertices.push_back(Point2d(p.x(), p.y()));
                }
            }
            for (Ccb_halfedge_circulator cit = f2->ccb(); cit != 0; ++cit) {
                if (cit->vertex()->is_finite()) {
                    Point_2 p = cit->vertex()->point();
                    cell_vertices.push_back(Point2d(p.x(), p.y()));
                }
            }
        }
    }

    // Remove duplicates and ensure proper ordering
    std::sort(cell_vertices.begin(), cell_vertices.end());
    cell_vertices.erase(std::unique(cell_vertices.begin(), cell_vertices.end()), cell_vertices.end());

    // Ensure we have at least 3 vertices
    if (cell_vertices.size() < 3) {
        // Create a default cell with a large bounding box
        cell_vertices = {
            Point2d(-1e10, -1e10),
            Point2d(1e10, -1e10),
            Point2d(-1e10, 1e10)
        };
    }

    result.push_back(cell_vertices);
}

// Handle unbounded cells (infinite faces)
for (VD::Face_iterator fit = vd.faces_begin(); fit != vd.faces_end(); ++fit) {
    if (fit->is_unbounded()) {
        std::vector<Point2d> cell_vertices;
        cell_vertices.reserve(3);

        // Get the infinite vertex
        Vertex_handle vh = fit->outer_ccb()->vertex();
        Point_2 v = vh->point();
        cell_vertices.push_back(Point2d(v.x(), v.y()));

        // Get the finite vertices
        for (Ccb_halfedge_circulator cit = fit->ccb(); cit != 0; ++cit) {
            if (cit->vertex()->is_finite()) {
                Point_2 p = cit->vertex()->point();
                cell_vertices.push_back(Point2d(p.x(), p.y()));
            }
        }

        // Ensure we have at least 3 vertices
        if (cell_vertices.size() < 3) {
            cell_vertices = {
                Point2d(-1e10, -1e10),
                Point2d(1e10, -1e10),
                Point2d(-1e10, 1e10)
            };
        }

        result.push_back(cell_vertices);
    }
}

return result;

